steps.code:
# Let's search for Splitwise expenses matching the descriptions from Venmo.
# We'll use the query parameter in show_group_expenses for each group.
descriptions = ["New TV for Parents", "Office Party", "New Laptop for Sibling"]
for group in groups:
    gid = group['group_id']
    for desc in descriptions:
        result = apis.splitwise.show_group_expenses(group_id=gid, access_token=splitwise_token, query=desc)
        if result:
            print(f"Group {gid} query '{desc}': {result}")

